const msg=$json.body.message;
const call=msg.toolCalls[0];
return [{json:{toolCallId:call.id,functionName:call.function.name,
  args: typeof call.function.arguments==='string' ? JSON.parse(call.function.arguments) : call.function.arguments}}];

const q=$('Extract Tool Call').first().json.args.query.toLowerCase();
const rows=$input.all().map(i=>i.json);
const hit=rows.find(r=>String(r.service_id).toLowerCase()===q||
  String(r.service_name_fr).toLowerCase().includes(q)||
  String(r.service_name_en).toLowerCase().includes(q));
if(!hit) return [{json:{result:`No service found matching "${q}".`}}];
let out=`${hit.service_name_en} / ${hit.service_name_fr} - ${hit.duration_min} min. `+
  `Prices: Nouveau-Talent ${hit.price_nouveau_talent}$, Specialiste ${hit.price_specialiste}$, `+
  `Senior ${hit.price_senior}$, Maitre ${hit.price_maitre}$, plus ${hit.green_fee}$ eco-fee and taxes.`;
if(hit.requires_consultation==='Yes') out+=' A free colour consultation is required first for new clients.';
return [{json:{result:out}}];

const args=$('Extract Tool Call').first().json.args;
const DUR={SVC001:60,SVC002:90,SVC003:120,SVC004:105,SVC005:120,SVC006:180,SVC007:240,SVC008:180,SVC009:240,SVC010:180,SVC011:240,SVC012:45,SVC013:75,SVC014:30,SVC015:30,SVC016:45,SVC017:15,SVC018:20};
const STY={STY001:{name:'Camille Tremblay',tier:'Nouveau-Talent',start:10,end:18,days:[2,3,4,5,6]},
  STY002:{name:'Sophie Nguyen',tier:'Spécialiste',start:9,end:17,days:[2,3,4,5,6]},
  STY003:{name:'Isabelle Roy',tier:'Sénior',start:10,end:19,days:[3,4,5,6]},
  STY004:{name:'Marc-André Fortin',tier:'Maître',start:10,end:18,days:[3,4,5]}};
let id=args.stylist_id;
if(!id&&args.tier) id=Object.keys(STY).find(k=>STY[k].tier===args.tier);
if(!id) id='STY002';
const s=STY[id];
const dur=DUR[args.service_id]||60;
const day=new Date(args.date+'T12:00:00').getDay();
if(!s.days.includes(day)) return [{json:{result:`${s.name} does not work on that day. Please suggest another date.`}}];
const events=$input.all().map(i=>i.json).filter(e=>e&&e.summary&&e.start&&e.start.dateTime&&e.summary.includes(s.name.split(' ')[0]));
const busy=events.map(e=>[new Date(e.start.dateTime).getTime(),new Date(e.end.dateTime).getTime()]);
const pad=n=>String(n).padStart(2,'0');
const slots=[];
for(let m=s.start*60;m+dur<=s.end*60;m+=30){
  const st=new Date(`${args.date}T${pad(Math.floor(m/60))}:${pad(m%60)}:00`).getTime();
  if(!busy.some(([b1,b2])=>st<b2&&st+dur*60000>b1)) slots.push(new Date(st));
  if(slots.length>=3) break;
}
if(!slots.length) return [{json:{result:`No openings for ${s.name} on ${args.date}. Suggest trying another day.`}}];
const fmt=d=>`${pad(d.getHours())}:${pad(d.getMinutes())}`;
return [{json:{result:`${s.name} (${s.tier}) has openings on ${args.date} at: ${slots.map(fmt).join(', ')}. The service takes ${dur} minutes.`,stylist_id:id}}];

const args=$('Extract Tool Call').first().json.args;
const DUR={SVC001:60,SVC002:90,SVC003:120,SVC004:105,SVC005:120,SVC006:180,SVC007:240,SVC008:180,SVC009:240,SVC010:180,SVC011:240,SVC012:45,SVC013:75,SVC014:30,SVC015:30,SVC016:45,SVC017:15,SVC018:20};
const SVC={SVC001:'toner/gloss',SVC002:'root colour',SVC003:'global colour',SVC004:'rootmelt',SVC005:'face framing',SVC006:'sunkissed balayage',SVC007:'go lighter balayage',SVC008:'half-head babylights',SVC009:'full-head babylights',SVC010:'half-head foilyage',SVC011:'full-head foilyage',SVC012:'blowout',SVC013:'cut and blowout',SVC014:'Olaplex treatment',SVC015:'Fusio-Dose treatment',SVC016:'Olaplex + Fusio-Dose',SVC017:'Eden Experience add-on',SVC018:'colour consultation'};
const STYN={STY001:'Camille Tremblay',STY002:'Sophie Nguyen',STY003:'Isabelle Roy',STY004:'Marc-André Fortin'};
const dur=DUR[args.service_id]||60;
const pad=n=>String(n).padStart(2,'0');
const start=new Date(`${args.date}T${args.start_time}:00`);
const end=new Date(start.getTime()+dur*60000);
const iso=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:00`;
const sty=STYN[args.stylist_id]||args.stylist_id;
return [{json:{...args,appointment_id:'APT'+Date.now(),service_name:SVC[args.service_id]||args.service_id,
  stylist_name:sty,startISO:iso(start),endISO:iso(end),
  end_time:`${pad(end.getHours())}:${pad(end.getMinutes())}`,
  summary:`${args.client_name} - ${SVC[args.service_id]||args.service_id} (${sty})`}}];

const args=$('Extract Tool Call').first().json.args;
const SVC={SVC001:'toner/gloss',SVC002:'root colour',SVC003:'global colour',SVC004:'rootmelt',SVC005:'face framing',SVC006:'sunkissed balayage',SVC007:'go lighter balayage',SVC008:'half-head babylights',SVC009:'full-head babylights',SVC010:'half-head foilyage',SVC011:'full-head foilyage',SVC012:'blowout',SVC013:'cut and blowout',SVC014:'Olaplex treatment',SVC015:'Fusio-Dose treatment',SVC016:'Olaplex + Fusio-Dose',SVC017:'Eden Experience add-on',SVC018:'colour consultation'};
const STYN={STY001:'Camille Tremblay',STY002:'Sophie Nguyen',STY003:'Isabelle Roy',STY004:'Marc-André Fortin'};
const digits=s=>String(s||'').replace(/\D/g,'');
const q=digits(args.client_phone);
let rows=$input.all().map(i=>i.json).filter(r=>digits(r.client_phone)===q&&r.status!=='cancelled');
if(args.date) rows=rows.filter(r=>r.date===args.date);
if(!rows.length) return [{json:{result:'No upcoming appointment found for that phone number.'}}];
const r=rows[0];
return [{json:{result:`Found: ${SVC[r.service_id]||r.service_id} with ${STYN[r.stylist_id]||r.stylist_id} on ${r.date} at ${r.start_time}. Confirmation ID ${r.appointment_id}.`,...r}}];

const args=$('Extract Tool Call').first().json.args;
const DUR={SVC001:60,SVC002:90,SVC003:120,SVC004:105,SVC005:120,SVC006:180,SVC007:240,SVC008:180,SVC009:240,SVC010:180,SVC011:240,SVC012:45,SVC013:75,SVC014:30,SVC015:30,SVC016:45,SVC017:15,SVC018:20};
const rows=$input.all().map(i=>i.json);
const r=rows.find(x=>x.appointment_id===args.appointment_id);
if(!r) return [{json:{result:`No appointment found with ID ${args.appointment_id}.`,appointment_id:args.appointment_id}}];
const dur=DUR[r.service_id]||60;
const pad=n=>String(n).padStart(2,'0');
const start=new Date(`${args.new_date}T${args.new_start_time}:00`);
const end=new Date(start.getTime()+dur*60000);
return [{json:{...r,date:args.new_date,start_time:args.new_start_time,end_time:`${pad(end.getHours())}:${pad(end.getMinutes())}`}}];

const r=$('Build Reschedule').first().json;
if(!r.date) return [{json:{result:r.result}}];
return [{json:{result:`Rescheduled ${r.appointment_id} to ${r.date} at ${r.start_time}.`}}];

const args=$('Extract Tool Call').first().json.args;
const rows=$input.all().map(i=>i.json);
const r=rows.find(x=>x.appointment_id===args.appointment_id);
if(!r) return [{json:{result:`No appointment found with ID ${args.appointment_id}.`,appointment_id:args.appointment_id}}];
return [{json:{...r,status:'cancelled',notes:((r.notes||'')+' | Cancelled: '+(args.reason||'no reason given')).trim()}}];

const r=$('Build Cancellation').first().json;
if(r.status!=='cancelled') return [{json:{result:r.result}}];
return [{json:{result:`Appointment ${r.appointment_id} has been cancelled.`}}];

const args=$('Extract Tool Call').first().json.args;
const q=args.product_query.toLowerCase();
const rows=$input.all().map(i=>i.json);
const hit=rows.find(r=>String(r.product_name).toLowerCase().includes(q));
if(!hit) return [{json:{result:`No product found matching "${q}".`,reserve:false}}];
const inStock=Number(hit.stock_qty)>0;
const price=hit.unit_price_cad?`, ${hit.unit_price_cad}$`:'';
return [{json:{result:inStock?`${hit.product_name} is in stock (${hit.stock_qty} left${price}).`:`${hit.product_name} is currently sold out.`,
  reserve:inStock&&!!args.reserve_for,sku:hit.sku,product_name:hit.product_name,
  client_name:args.reserve_for||'',timestamp:new Date().toISOString()}}];

const toolCallId=$('Extract Tool Call').first().json.toolCallId;
const result=$json.result||'Done.';
return [{json:{results:[{toolCallId,result}]}}];
